package dev.thedocruby.resounding.debug;

import dev.thedocruby.resounding.debug.math.RingBuffer;
import dev.thedocruby.resounding.material.Material;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.util.math.Vec3d;
import org.jetbrains.annotations.Nullable;

import java.util.List;

@Environment(EnvType.CLIENT)
public final class CaptureBuffer {

	public static final CaptureBuffer INSTANCE = new CaptureBuffer(MAX_CAPTURED_SEGMENTS);

	private static final int MAX_CAPTURED_SEGMENTS = 16384;

	public record CapturedRay(
			Vec3d start,
			Vec3d end,
			int color,
			int soundEventId,
			int bounceIndex,
			@Nullable Material material
	) {}

	private final int maxSegments;
	private RingBuffer<CapturedRay> segments;
	private int remaining;
	private boolean truncationWarningPending;
	private boolean truncationWarningFired;
	private int version;

	CaptureBuffer(int maxSegments) {
		this.maxSegments = maxSegments;
		this.segments = new RingBuffer<>(maxSegments);
	}

	public void startCapture(int events) {
		remaining = events;
		segments = new RingBuffer<>(maxSegments);
		truncationWarningPending = false;
		truncationWarningFired = false;
		version++;
	}

	public void stopCapture() {
		remaining = 0;
		version++;
	}

	public boolean isCapturing() {
		return remaining != 0;
	}

	public void onSoundEvalStart() {
	}

	public void onSoundEvalEnd() {
		if (remaining > 0) {
			remaining--;
			version++;
		}
	}

	public void offer(CapturedRay ray) {
		if (!isCapturing()) {
			return;
		}
		if (segments.size() == maxSegments) {
			if (!truncationWarningFired) {
				truncationWarningPending = true;
				truncationWarningFired = true;
			}
		}
		segments.offer(ray);
		version++;
	}

	public boolean consumeTruncationWarning() {
		if (truncationWarningPending) {
			truncationWarningPending = false;
			return true;
		}
		return false;
	}

	public List<CapturedRay> asCapturedList() {
		return segments.asList();
	}

	public int version() {
		return version;
	}
}

package dev.thedocruby.resounding.debug;

import dev.thedocruby.resounding.Engine;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;
import net.minecraft.client.option.KeyBinding;
import net.minecraft.client.util.InputUtil;
import org.lwjgl.glfw.GLFW;

@Environment(EnvType.CLIENT)
public final class DebugKeybinds {

	private static final String CATEGORY = "key.categories.resounding.debug";

	private static final KeyBinding TOGGLE_BOUNCE_RAYS = KeyBindingHelper.registerKeyBinding(
			new KeyBinding(
					"key.resounding.debug.toggle_bounce_rays",
					InputUtil.Type.KEYSYM,
					GLFW.GLFW_KEY_B,
					CATEGORY
			)
	);
	private static final KeyBinding TOGGLE_OCCLUSION_RAYS = KeyBindingHelper.registerKeyBinding(
			new KeyBinding(
					"key.resounding.debug.toggle_occlusion_rays",
					InputUtil.Type.KEYSYM,
					GLFW.GLFW_KEY_N,
					CATEGORY
			)
	);
	private static final KeyBinding TOGGLE_OCTREE = KeyBindingHelper.registerKeyBinding(
			new KeyBinding(
					"key.resounding.debug.toggle_octree",
					InputUtil.Type.KEYSYM,
					GLFW.GLFW_KEY_O,
					CATEGORY
			)
	);
	private static final KeyBinding TOGGLE_CAPTURE = KeyBindingHelper.registerKeyBinding(
			new KeyBinding(
					"key.resounding.debug.toggle_capture",
					InputUtil.Type.KEYSYM,
					GLFW.GLFW_KEY_C,
					CATEGORY
			)
	);

	private DebugKeybinds() {}

	public static void register() {
		ClientTickEvents.END_CLIENT_TICK.register(client -> {
			if (!Engine.isActive) {
				return;
			}

			while (TOGGLE_BOUNCE_RAYS.wasPressed()) {
				var layer = DebugRenderDispatcher.INSTANCE.bounceRays();
				layer.setEnabled(!layer.isEnabled());
			}
			while (TOGGLE_OCCLUSION_RAYS.wasPressed()) {
				var layer = DebugRenderDispatcher.INSTANCE.occlusionRays();
				layer.setEnabled(!layer.isEnabled());
			}
			while (TOGGLE_OCTREE.wasPressed()) {
				var layer = DebugRenderDispatcher.INSTANCE.octree();
				layer.setEnabled(!layer.isEnabled());
			}
			while (TOGGLE_CAPTURE.wasPressed()) {
				// Default: capture exactly the next sound event.
				// An open-ended / held-key variant is a possible future enhancement.
				if (CaptureBuffer.INSTANCE.isCapturing()) {
					CaptureBuffer.INSTANCE.stopCapture();
				} else {
					CaptureBuffer.INSTANCE.startCapture(1);
				}
			}
		});
	}
}

package dev.thedocruby.resounding.debug;

import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gl.VertexBuffer;
import net.minecraft.client.render.BufferBuilder;
import net.minecraft.client.util.math.MatrixStack;
import net.minecraft.text.Text;
import net.minecraft.util.math.Vec3d;

@Environment(EnvType.CLIENT)
public final class CaptureLayer implements DebugLayer {

	private final GpuLineBuffer buffer = new GpuLineBuffer(VertexBuffer.Usage.STATIC, true, 0.25F);
	private int lastVersion = -1;

	@Override
	public boolean isEnabled() {
		// Visible while capturing or while frozen capture data remains on screen.
		return CaptureBuffer.INSTANCE.isCapturing() || !CaptureBuffer.INSTANCE.asCapturedList().isEmpty();
	}

	@Override
	public void update() {
		int version = CaptureBuffer.INSTANCE.version();
		if (version != lastVersion) {
			lastVersion = version;
			buffer.markDirty();
		}

		if (CaptureBuffer.INSTANCE.consumeTruncationWarning()) {
			MinecraftClient client = MinecraftClient.getInstance();
			if (client.player != null) {
				client.player.sendMessage(Text.literal("Capture buffer full; oldest rays dropped."), true);
			}
		}
	}

	@Override
	public void render(MatrixStack matrices, Vec3d cameraPos) {
		buffer.rebuild(this::populate);
		buffer.draw(matrices, cameraPos);
	}

	private void populate(BufferBuilder builder) {
		for (CaptureBuffer.CapturedRay ray : CaptureBuffer.INSTANCE.asCapturedList()) {
			GpuLineBuffer.line(
					builder,
					ray.start().x, ray.start().y, ray.start().z,
					ray.end().x, ray.end().y, ray.end().z,
					ray.color()
			);
		}
	}
}

